import {validateMessage} from './validation.js';
import type {
  IncomingMessage,
  ListSessionsMessage,
  OutgoingMessage,
  SessionListMessage,
  SessionSummaryFrame,
} from '../../index.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('validates list_sessions with optional limit and before cursor and drops unknown fields', () => {
    const summary: SessionSummaryFrame = {
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:01:00.000Z',
      entryCount: 2,
    };
    const outbound: OutgoingMessage = {type: 'session_list', sessions: [summary]} satisfies SessionListMessage;
    const inbound: IncomingMessage = {
      type: 'list_sessions',
      limit: 10,
      before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'},
    } satisfies ListSessionsMessage;

    expect({
      outbound,
      bare: validateMessage({type: 'list_sessions', userId: 'u2'}),
      paged: validateMessage({...inbound, userId: 'u2'}),
      numericBefore: validateMessage({type: 'list_sessions', limit: 0, before: {updatedAt: 1700000000000, sessionId: 's1'}}),
      badLimits: [
        validateMessage({type: 'list_sessions', limit: 'ten'}).valid,
        validateMessage({type: 'list_sessions', limit: -1}).valid,
        validateMessage({type: 'list_sessions', limit: 1.5}).valid,
      ],
      badBefores: [
        validateMessage({type: 'list_sessions', before: 'not-an-object'}).valid,
        validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}}).valid,
        validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}}).valid,
        validateMessage({type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}}).valid,
        validateMessage({type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}}).valid,
      ],
    }).toEqual({
      outbound: {type: 'session_list', sessions: [summary]},
      bare: {valid: true, data: {type: 'list_sessions'}},
      paged: {valid: true, data: inbound},
      numericBefore: {valid: true, data: {type: 'list_sessions', limit: 0, before: {updatedAt: 1700000000000, sessionId: 's1'}}},
      badLimits: [false, false, false],
      badBefores: [false, false, false, false, false],
    });
  });
});

